const Signal=(()=>{
const N=2048,HOP=N/2;
function fft(re,im){const n=re.length;for(let i=1,j=0;i<n;i++){let bit=n>>1;for(;j&bit;bit>>=1)j^=bit;j^=bit;if(i<j){[re[i],re[j]]=[re[j],re[i]];[im[i],im[j]]=[im[j],im[i]];}}for(let len=2;len<=n;len<<=1){const a=-2*Math.PI/len,wr0=Math.cos(a),wi0=Math.sin(a);for(let i=0;i<n;i+=len){let wr=1,wi=0;for(let j=0;j<len/2;j++){const k=i+j,l=k+len/2,tr=wr*re[l]-wi*im[l],ti=wr*im[l]+wi*re[l];re[l]=re[k]-tr;im[l]=im[k]-ti;re[k]+=tr;im[k]+=ti;const next=wr*wr0-wi*wi0;wi=wr*wi0+wi*wr0;wr=next;}}}}
function db(v){return v>0?20*Math.log10(v):null;}
function analyze(channels,sampleRate){if(!channels.length||!channels[0].length||!Number.isFinite(sampleRate)||sampleRate<=0)throw Error('Invalid PCM');const length=channels[0].length;let squares=0,peak=0,near=0,count=0;const mono=new Float32Array(length);for(const channel of channels){if(channel.length!==length)throw Error('Channel length mismatch');for(let i=0;i<length;i++){const v=channel[i];if(!Number.isFinite(v))throw Error('Invalid PCM sample');squares+=v*v;peak=Math.max(peak,Math.abs(v));if(Math.abs(v)>=.98)near++;count++;mono[i]+=v/channels.length;}}
const spectrum=new Float64Array(N/2+1),win=Float64Array.from({length:N},(_,i)=>.5-.5*Math.cos(2*Math.PI*i/(N-1)));let frames=0;for(let offset=0;offset+N<=length;offset+=HOP){const re=new Float64Array(N),im=new Float64Array(N);for(let j=0;j<N;j++)re[j]=mono[offset+j]*win[j];fft(re,im);for(let k=1;k<=N/2;k++)spectrum[k]+=re[k]*re[k]+im[k]*im[k];frames++;}let total=0,weighted=0,max=0,dominant=null;for(let k=1;k<spectrum.length;k++){spectrum[k]=frames?spectrum[k]/frames:0;total+=spectrum[k];weighted+=spectrum[k]*k*sampleRate/N;if(spectrum[k]>max){max=spectrum[k];dominant=k*sampleRate/N;}}const rms=Math.sqrt(squares/count);const waveform=[];const columns=520,step=Math.max(1,Math.floor(length/columns));for(let i=0;i<length;i+=step){let min=1,maxVal=-1;for(let j=i;j<Math.min(length,i+step);j++){min=Math.min(min,mono[j]);maxVal=Math.max(maxVal,mono[j]);}waveform.push([min,maxVal]);}
return{method:'pcm-hann-fft-v2',duration:length/sampleRate,sampleRate,channels:channels.length,sampleCount:count,rms,rmsDb:db(rms),peak,peakDb:db(peak),nearLimitPct:near/count*100,dominantHz:dominant,centroidHz:total>0?weighted/total:null,binHz:sampleRate/N,fftSize:N,frames,spectrum:Array.from(spectrum),waveform};}
function similarity(a,b){if(a.sampleRate!==b.sampleRate||a.spectrum.length!==b.spectrum.length)return null;let dot=0,aa=0,bb=0;for(let i=1;i<a.spectrum.length;i++){dot+=a.spectrum[i]*b.spectrum[i];aa+=a.spectrum[i]**2;bb+=b.spectrum[i]**2;}return aa>0&&bb>0?Math.min(1,Math.max(0,dot/Math.sqrt(aa*bb))):null;}
function synth({freq=180,amp=.16,seed=1,duration=12,sampleRate=16000}){let rng=seed>>>0;const pcm=new Float32Array(duration*sampleRate);for(let i=0;i<pcm.length;i++){rng=(Math.imul(rng,1664525)+1013904223)>>>0;const noise=(rng/4294967296*2-1),t=i/sampleRate,env=.6+.4*Math.sin(Math.PI*1.2*t)**2;const v=amp*env*(.7*Math.sin(2*Math.PI*freq*t)+.2*Math.sin(2*Math.PI*freq*2*t)+.1*noise);pcm[i]=Math.round(Math.max(-1,Math.min(1,v))*32767)/32768;}return pcm;}
function wav(pcm,sampleRate){const buffer=new ArrayBuffer(44+pcm.length*2),v=new DataView(buffer);function textAt(pos,s){for(let i=0;i<s.length;i++)v.setUint8(pos+i,s.charCodeAt(i));}textAt(0,'RIFF');v.setUint32(4,36+pcm.length*2,true);textAt(8,'WAVE');textAt(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,sampleRate,true);v.setUint32(28,sampleRate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);textAt(36,'data');v.setUint32(40,pcm.length*2,true);for(let i=0;i<pcm.length;i++)v.setInt16(44+i*2,Math.round(pcm[i]*32768),true);return new Blob([buffer],{type:'audio/wav'});}
return{analyze,similarity,synth,wav};})();
if(typeof module!=='undefined')module.exports=Signal;
